css:
@font-face{font-family:"Italiana";src:url("fonts/Italiana-TR.ttf")}
@font-face{font-family:"Instrument Serif";src:url("fonts/InstrumentSerif-Regular.ttf")}
@font-face{font-family:"Instrument Serif";font-style:italic;src:url("fonts/InstrumentSerif-Italic.ttf")}
@font-face{font-family:"Crimson Pro";src:url("fonts/CrimsonPro-Regular.ttf")}
@font-face{font-family:"Crimson Pro";font-style:italic;src:url("fonts/CrimsonPro-Italic.ttf")}
@font-face{font-family:"Crimson Pro";font-weight:700;src:url("fonts/CrimsonPro-Bold.ttf")}

*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{font-family:"Crimson Pro",serif;color:#2A1620;-webkit-print-color-adjust:exact;print-color-adjust:exact}
.page{width:280.0mm;height:210.0mm;position:relative;overflow:hidden;break-after:page;background:#FAF5EE}
.page.dark{background:#3A1A28}
.inner{width:210mm;height:157.500mm;transform:scale(1.33333);transform-origin:0 0;padding:16mm 17mm 15mm;display:flex;flex-direction:column;gap:5mm;position:relative}
.inner.nopad{padding:0;align-items:center;justify-content:center}
.inner>*{flex-shrink:0}

/* header */
.hdr{display:flex;align-items:center;gap:5mm;padding-bottom:3.5mm;border-bottom:0.6pt solid #3A1A28}
.hnum{font-family:"Instrument Serif",serif;font-size:44pt;line-height:.85;color:#B08D57;min-width:16mm}
.hbar{width:0.6pt;align-self:stretch;background:#B08D57}
.htxt{flex:1;display:flex;flex-direction:column;gap:1.2mm}
.htitle{font-family:"Italiana",serif;font-size:21pt;letter-spacing:.2em;color:#3A1A28;line-height:1}
.hsub{font-family:"Instrument Serif",serif;font-style:italic;font-size:11.5pt;color:#7A5A66}
.hright{display:flex;align-items:flex-end;gap:2mm;align-self:flex-end}
.pgno{font-family:"Instrument Serif",serif;font-size:22pt;color:#B08D57}
.wk-of{font-family:"Instrument Serif",serif;font-style:italic;font-size:10.5pt;color:#7A5A66}
.blank-l{display:inline-block;width:38mm;border-bottom:0.5pt solid #B08D57;height:5mm}

/* generic */
.lbl{font-family:"Italiana",serif;font-size:9.5pt;letter-spacing:.22em;text-transform:uppercase;color:#3A1A28;padding-bottom:1.4mm}
.ln{border-bottom:0.5pt solid #CDB89A}
.ln.ck{display:flex;align-items:flex-end;padding-bottom:1.3mm}
.box{width:3mm;height:3mm;border:0.6pt solid #B08D57;display:inline-block}
.blk{display:flex;flex-direction:column;min-width:0}
.blk.fill{flex:1 1 0;min-height:12mm}
.ruled{flex:1 1 0;min-height:7mm;background-image:repeating-linear-gradient(to bottom,transparent 0,transparent 6.95mm,#CDB89A 6.95mm,#CDB89A 7.2mm)}
.two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8mm}
.three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6mm}
.col{display:flex;flex-direction:column;min-height:0}
.center-col{display:flex;flex-direction:column;align-items:center}
.dia{display:inline-block;border:0.6pt solid;transform:rotate(45deg);margin:0 1.3mm}
.note-box{border:0.5pt solid #CDB89A;background:#F2E9DC;padding:4mm 5mm}

/* cover & divider */
.arch,.arch2,.frame1{position:absolute;pointer-events:none}
.arch{top:14%;bottom:11%;left:14.5%;right:14.5%;border:0.8pt solid;border-radius:999mm 999mm 0 0}
.arch2{top:15.3%;bottom:12.2%;left:16.2%;right:16.2%;border:0.5pt solid;border-radius:999mm 999mm 0 0;opacity:.6}
.frame1{top:7mm;bottom:7mm;left:7mm;right:7mm;border:0.6pt solid}
.cov{display:flex;flex-direction:column;align-items:center;text-align:center;position:relative}
.cov-roman{font-family:"Italiana",serif;font-size:10.5pt;letter-spacing:.5em;padding-left:.5em}
.cov-year{font-family:"Instrument Serif",serif;font-size:122pt;line-height:.9;margin-top:5mm}
.cov-title{font-family:"Italiana",serif;font-size:21pt;letter-spacing:.34em;padding-left:.34em}
.cov-sub{font-family:"Instrument Serif",serif;font-style:italic;font-size:14pt;margin-top:4mm}
.div-num{font-family:"Instrument Serif",serif;font-size:150pt;line-height:.85}
.div-month{font-family:"Italiana",serif;font-size:34pt;letter-spacing:.3em;padding-left:.3em;margin-top:6mm}
.div-line{font-family:"Instrument Serif",serif;font-style:italic;font-size:16pt}

/* belongs */
.big-italic{font-family:"Instrument Serif",serif;font-style:italic;font-size:26pt;color:#3A1A28}
.name-line{width:120mm;border-bottom:0.6pt solid #B08D57;height:12mm}

/* how to */
.howlist{display:flex;flex-direction:column;justify-content:space-evenly;flex:1;padding:2mm 0}
.howrow{display:grid;grid-template-columns:14mm 1fr;gap:4mm;align-items:start}
.hownum{font-family:"Instrument Serif",serif;font-size:20pt;color:#B08D57;line-height:1}
.howt{font-family:"Italiana",serif;font-size:12pt;letter-spacing:.18em;text-transform:uppercase;color:#3A1A28}
.howd{font-size:11pt;line-height:1.45;color:#2A1620;margin-top:1mm}

/* key */
.keyrow{display:flex;align-items:center;gap:4mm;height:8.2mm;border-bottom:0.5pt solid #CDB89A}
.keysym{width:8mm;text-align:center;font-size:15pt;color:#3A1A28;display:flex;justify-content:center}
.keytxt{font-size:11.5pt}
.keybox{width:7mm;height:6mm;border:0.5pt solid #B08D57}
.keyrow .ln{border-bottom:none}
.swatch{width:6mm;height:6mm;border-radius:50%;border:0.6pt solid #B08D57}

/* index */
.idxhead{display:flex;justify-content:space-between;font-family:"Instrument Serif",serif;font-style:italic;font-size:11pt;color:#7A5A66}
.idxrow{display:flex;gap:4mm;align-items:flex-end}
.idxpg{width:22mm;height:8mm;border-bottom:0.5pt solid #B08D57}

/* at a glance */
.glance{flex:1;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:repeat(4,minmax(0,1fr));gap:5mm 7mm}
.mm{display:flex;flex-direction:column;gap:1.5mm}
.mm-t{font-family:"Italiana",serif;font-size:10pt;letter-spacing:.2em;color:#3A1A28;border-bottom:0.5pt solid #B08D57;padding-bottom:1mm}
.mm-g{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));row-gap:1mm;text-align:center;font-size:9pt;font-variant-numeric:tabular-nums}
.mm-h{font-family:"Instrument Serif",serif;font-style:italic;color:#B08D57}
.mm-hol,.mm-obs{display:inline-flex;align-items:center;justify-content:center;width:4.4mm;height:4.4mm;border-radius:50%;font-weight:400;box-sizing:border-box}
.mm-hol{background:#B08D57;color:#FAF5EE}
.mm-obs{border:0.6pt solid #B08D57;color:#3A1A28}
.lg{font-size:7pt;margin-right:1mm;font-style:normal;font-family:"Crimson Pro",serif}
.legend span{margin-right:5mm}
.lg-note{margin-left:auto;margin-right:0!important}
.legend{display:flex;align-items:center;gap:2mm;font-family:"Instrument Serif",serif;font-style:italic;font-size:10pt;color:#7A5A66}

/* reflection / intentions */
.wordbox{height:14mm;border:0.5pt solid #B08D57}
.wordyear{border:0.6pt solid #B08D57;outline:0.4pt solid #B08D57;outline-offset:1.2mm;padding:5mm 8mm;display:flex;align-items:flex-end;gap:6mm;margin:1.5mm}
.wy-line{flex:1;border-bottom:0.5pt solid #CDB89A;height:9mm}
.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5mm 8mm}

/* vision */
.vision{flex:1;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:repeat(4,minmax(0,1fr));gap:5mm}
.vb{border:0.6pt solid #B08D57;background:#F2E9DC}
.vb.arch-top{border-radius:999mm 999mm 0 0}

/* future log, birthdays */
.flgrid{flex:1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:repeat(3,minmax(0,1fr));gap:6mm 8mm}
.fl{display:flex;flex-direction:column;min-height:0}
.fl-h{display:flex;align-items:baseline;gap:3mm;border-bottom:0.6pt solid #3A1A28;padding-bottom:1.2mm;margin-bottom:.5mm}
.fl-n{font-family:"Instrument Serif",serif;font-size:17pt;color:#B08D57;line-height:1}
.fl-m{font-family:"Italiana",serif;font-size:11pt;letter-spacing:.22em;color:#3A1A28}
.bdgrid{flex:1;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:repeat(4,minmax(0,1fr));gap:5mm 7mm}
.bd{display:flex;flex-direction:column}
.bd .fl-m{border-bottom:0.6pt solid #3A1A28;padding-bottom:1mm}

/* monthly calendar */
.cal{flex:1;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));border-top:0.8pt solid #3A1A28;border-left:0.5pt solid #CDB89A}
.cal-h{font-family:"Italiana",serif;font-size:9.5pt;letter-spacing:.2em;text-align:center;padding:2mm 0;background:#F2E9DC;border-right:0.5pt solid #CDB89A;border-bottom:0.5pt solid #CDB89A;color:#3A1A28}
.cal-c{border-right:0.5pt solid #CDB89A;border-bottom:0.5pt solid #CDB89A;padding:1.4mm 1.8mm;display:flex;flex-direction:column;align-items:flex-end;gap:.6mm;min-height:0;overflow:hidden}
.cal-c.out{background:#F4ECE0}
.cal-d{font-family:"Instrument Serif",serif;font-size:14pt;line-height:1;color:#3A1A28}
.cal-hol{font-family:"Instrument Serif",serif;font-style:italic;font-size:7.5pt;line-height:1.1;color:#7A5A66;text-align:right}
.cal-hol.off{color:#9A7442}
.cal-d.off{color:#B08D57}

/* focus */
.goalrow{display:flex;align-items:flex-end;gap:3mm}
.gnum{font-family:"Instrument Serif",serif;font-size:15pt;color:#B08D57;width:5mm;line-height:1.1}
.hb{display:grid;border-top:0.6pt solid #3A1A28}
.hb-d,.hb-w{font-size:6.6pt;text-align:center;color:#7A5A66;padding:.6mm 0;font-variant-numeric:tabular-nums}
.hb-w{font-family:"Instrument Serif",serif;font-style:italic;color:#B08D57}
.hb-name{border-bottom:0.5pt solid #CDB89A;height:6.6mm}
.hb-name.hb-blank{border-bottom:none;height:auto}
.hb-c{border-bottom:0.5pt solid #CDB89A;border-left:0.4pt solid #E3D6C3;height:6.6mm}

/* review */
.moods{display:flex;gap:4mm}
.mood{display:flex;flex-direction:column;align-items:center;gap:1.2mm}
.mood-c{width:8mm;height:8mm;border-radius:50%;border:0.6pt solid #B08D57}
.mood-t{font-family:"Instrument Serif",serif;font-style:italic;font-size:9pt;color:#7A5A66}
.rating{display:flex;gap:2mm;padding:3mm 0 4mm}

/* weekly */
.wvgrid{flex:1;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:2.6mm}
.wv,.wh{display:flex;flex-direction:column;min-height:0}
.wv-h{display:flex;justify-content:space-between;align-items:center;font-family:"Italiana",serif;font-size:9.5pt;letter-spacing:.14em;color:#3A1A28;border-bottom:0.6pt solid #3A1A28;padding-bottom:1.2mm}
.wv-date{display:inline-block;width:6mm;border-bottom:0.5pt solid #B08D57;height:3.5mm}
.whgrid{flex:1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:repeat(4,minmax(0,1fr));gap:5mm 8mm}
.wh.focus{background:#F2E9DC;padding:2.5mm 3mm;border:0.5pt solid #B08D57}

/* daily */
.sched{flex:1;display:flex;flex-direction:column}
.hr{flex:1;display:flex;align-items:flex-end;gap:2mm}
.hr .ln{height:100%}
.hr-n{font-family:"Instrument Serif",serif;font-size:11pt;color:#B08D57;width:6mm;text-align:right;padding-bottom:.6mm}
.water{display:flex;gap:2.5mm;padding-top:1mm}

/* meals */
.meals{flex:1;display:grid;grid-template-columns:14mm repeat(4,minmax(0,1fr));grid-template-rows:auto repeat(7,minmax(0,1fr));border-top:0.6pt solid #3A1A28}
.ml-h{font-family:"Italiana",serif;font-size:9pt;letter-spacing:.18em;text-transform:uppercase;padding:2mm 1mm;text-align:center;border-bottom:0.5pt solid #CDB89A}
.ml-d{font-family:"Italiana",serif;font-size:9.5pt;letter-spacing:.14em;color:#B08D57;border-bottom:0.5pt solid #CDB89A;display:flex;align-items:center}
.ml-c{border-bottom:0.5pt solid #CDB89A;border-left:0.5pt solid #CDB89A}

/* tables */
.tbl{display:grid;border-top:0.6pt solid #3A1A28}
.tb-h{font-family:"Italiana",serif;font-size:8.5pt;letter-spacing:.12em;white-space:nowrap;text-transform:uppercase;padding:1.8mm 1.5mm;background:#F2E9DC;border-bottom:0.5pt solid #CDB89A}
.tb-c{border-bottom:0.5pt solid #CDB89A;min-height:7.6mm;padding:0 1.5mm;display:flex;align-items:center}
.tb-r{justify-content:flex-start}
.goalbox{display:flex;align-items:flex-end;width:90mm}
.wl .tb-c{min-height:0}
.wl-n{font-family:"Instrument Serif",serif;font-size:10pt;color:#B08D57}
.wl-w{gap:1.4mm}
.wl-w i,.wl-b i{display:inline-block;width:3mm;height:3mm;border:0.5pt solid #B08D57;border-radius:50%}
.wl-b i{border-radius:0}
.wl-b i.o{border-radius:50%}
.sumrow{display:flex;align-items:flex-end;gap:3mm;font-family:"Instrument Serif",serif;font-style:italic;font-size:11pt;color:#7A5A66}
.sumrow span{width:22mm}

/* bookshelf */
.shelves{flex:1;display:flex;flex-direction:column;padding:2mm 3mm}
.shelf{flex:1;display:flex;align-items:flex-end;gap:1.2mm;padding:0 2mm}
.spine{border:0.6pt solid #3A1A28;border-bottom:none;position:relative;background:#FAF5EE}
.band{position:absolute;left:0;right:0;top:12%;border-top:0.5pt solid #B08D57}
.band.b2{top:16%}
.plank{height:3mm;background:#3A1A28;margin-bottom:5mm}

/* savings */
.svgrid{display:grid;grid-template-columns:repeat(10,minmax(0,1fr));gap:2.2mm 3.4mm;padding:1mm 16mm}
.sv{aspect-ratio:1;border:0.6pt solid #B08D57;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:7.5pt;color:#7A5A66}

/* gratitude */
.grlist{flex:1;display:flex;flex-direction:column}
.gr{flex:1;display:flex;align-items:flex-end;gap:3mm}
.gr .ln{height:100%}
.gr-n{font-family:"Instrument Serif",serif;font-size:11pt;color:#B08D57;width:7mm;text-align:right;padding-bottom:.6mm}

/* notes */
.nt{flex:1}
.nt-dot{background-image:radial-gradient(circle,#B9A27E 0.32mm,transparent 0.42mm);background-size:5mm 5mm;background-position:2.5mm 2.5mm}
.nt-lined{background-image:repeating-linear-gradient(to bottom,transparent 0,transparent 7.75mm,#CDB89A 7.75mm,#CDB89A 8mm)}
.nt-grid{background-image:linear-gradient(to right,#E3D6C3 0.25mm,transparent 0.25mm),linear-gradient(to bottom,#E3D6C3 0.25mm,transparent 0.25mm);background-size:5mm 5mm;border-right:0.25mm solid #E3D6C3;border-bottom:0.25mm solid #E3D6C3}
.nt-blank{border:0.5pt solid #CDB89A}

/* prompts */
.prlist{flex:1;display:flex;flex-direction:column;justify-content:space-between}
.pr{display:flex;align-items:baseline;gap:4mm;border-bottom:0.5pt solid #E3D6C3;padding:1.2mm 0}
.pr-n{font-family:"Instrument Serif",serif;font-size:13pt;color:#B08D57;width:8mm}
.pr-t{font-size:11.5pt}

/* stickers */
.stgrid{display:grid;gap:4mm;margin-bottom:4mm}
.g2{grid-template-columns:repeat(2,minmax(0,1fr))}.g3{grid-template-columns:repeat(3,minmax(0,1fr))}
.g4{grid-template-columns:repeat(4,minmax(0,1fr))}.g6{grid-template-columns:repeat(6,minmax(0,1fr))}
.g8{grid-template-columns:repeat(8,minmax(0,1fr))}
.st{display:flex;align-items:center;justify-content:center;text-align:center;min-height:12mm}
.st.pill{border:0.6pt solid #3A1A28;border-radius:999mm;box-shadow:0 0 0 1mm #FAF5EE,0 0 0 1.25mm #B08D57;font-family:"Italiana",serif;letter-spacing:.14em;font-size:10pt;text-transform:uppercase;margin:1.3mm}
.st.stamp{border:1pt dashed #3A1A28;color:#3A1A28;font-family:"Italiana",serif;letter-spacing:.14em;font-size:9pt;transform:rotate(-5deg)}
.st.tab{background:#3A1A28;color:#C9A86A;font-family:"Italiana",serif;letter-spacing:.16em;font-size:9pt;min-height:18mm;clip-path:polygon(0 0,100% 0,100% 100%,50% 82%,0 100%);padding-bottom:3mm}
.st.circ{aspect-ratio:1;border-radius:50%;border:0.6pt solid #B08D57;font-family:"Instrument Serif",serif;font-size:16pt;color:#3A1A28;min-height:0}
.st.label{border:0.6pt solid #B08D57;outline:0.4pt solid #B08D57;outline-offset:1mm;font-family:"Instrument Serif",serif;font-style:italic;font-size:13pt;color:#3A1A28;margin:1mm}
.st.darklbl{background:#3A1A28;color:#FAF5EE;font-family:"Italiana",serif;letter-spacing:.18em;text-transform:uppercase;font-size:10pt;min-height:14mm;box-shadow:inset 0 0 0 1.3mm #3A1A28,inset 0 0 0 1.55mm #C9A86A}
.st.quote{background:#3A1A28;color:#C9A86A;font-family:"Instrument Serif",serif;font-style:italic;font-size:20pt;min-height:36mm;box-shadow:inset 0 0 0 2.5mm #3A1A28,inset 0 0 0 2.8mm #C9A86A}

.tnum{font-family:"Instrument Serif",serif;font-size:1.18em;letter-spacing:.06em;line-height:0}

.wl .tb-h{font-size:7.6pt;letter-spacing:.06em;white-space:normal;line-height:1.15}

/* ---- extra pages ---- */
.yg{flex:1 1 0;min-height:0;display:grid;grid-template-columns:7mm repeat(12,minmax(0,1fr));grid-template-rows:auto repeat(31,minmax(0,1fr));gap:.7mm}
.yg-h{font-family:"Italiana",serif;font-size:8pt;letter-spacing:.08em;text-align:center;color:#3A1A28;padding-bottom:1mm}
.yg-n{font-family:"Instrument Serif",serif;font-size:8.5pt;color:#B08D57;text-align:right;padding-right:1.2mm;display:flex;align-items:center;justify-content:flex-end}
.yg-c{border:0.5pt solid #CDB89A}
.yg-c.rd{border-radius:1.4mm}
.yg-c.x{background:#F4ECE0;border-color:#EADFCD}
.swrow{display:flex;flex-wrap:wrap;gap:3mm 6mm}
.swi{display:flex;align-items:center;gap:1.8mm;font-family:"Instrument Serif",serif;font-style:italic;font-size:10.5pt;color:#7A5A66}
.swb{width:5mm;height:5mm;border:0.6pt solid #B08D57;border-radius:1mm}
.tb-h.c,.tb-c.c{justify-content:center;text-align:center}
.tb-c.n{font-family:"Instrument Serif",serif;color:#B08D57}
.box.sm{width:2.6mm;height:2.6mm}
.bills .tb-h{padding:1.8mm .4mm;font-size:7.4pt;letter-spacing:.05em}
.filltbl{flex:1 1 0;min-height:0;align-content:start;overflow:hidden}
.filltbl .tb-c{min-height:0}
.fld{display:flex;align-items:flex-end;gap:2.5mm;min-width:0}
.fld-l{font-family:"Italiana",serif;font-size:9pt;letter-spacing:.18em;text-transform:uppercase;color:#3A1A28;white-space:nowrap;padding-bottom:1mm}
.fld-v{flex:1;border-bottom:0.5pt solid #CDB89A;height:8mm;min-width:8mm}
.dbgrid{display:grid;grid-template-columns:repeat(10,minmax(0,1fr));gap:1.6mm}
.dbx{height:7.5mm;border:0.5pt solid #B08D57;display:flex;align-items:flex-end;justify-content:flex-end;padding:.5mm .8mm;font-size:6.5pt;color:#7A5A66}
.nsgrid{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:3mm 5mm;padding:2mm 8mm}
.ns,.ch{aspect-ratio:1;border:0.6pt solid #B08D57;border-radius:50%;display:flex;align-items:center;justify-content:center;font-family:"Instrument Serif",serif;font-size:13pt;color:#3A1A28}
.chgrid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:3.5mm 7mm;padding:1mm 12mm}
.ch{font-size:15pt}
.cal-blank{width:7mm;height:5mm;border-bottom:0.5pt solid #B08D57}
.pgbar{display:grid;grid-template-columns:repeat(10,minmax(0,1fr));gap:1.6mm}
.pg{height:9mm;border:0.6pt solid #B08D57;display:flex;align-items:flex-end;justify-content:center;font-size:7.5pt;color:#7A5A66;padding-bottom:.6mm}
.rc{display:grid;grid-template-columns:0.9fr 1.3fr;gap:8mm}
.tbl.tall .tb-c{min-height:11mm}
.tb-c.wd{font-family:"Italiana",serif;font-size:9.5pt;letter-spacing:.12em;color:#B08D57}
.ln.sc{align-items:flex-end}
.sct{margin-left:2.6mm;font-size:10.5pt;line-height:1}
.quote{padding:3.5mm 5mm}
.gnum.bk{font-size:11pt;width:7mm}
.ctgrid{flex:1 1 0;min-height:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:repeat(5,minmax(0,1fr));gap:4mm 8mm}
.ct{display:flex;flex-direction:column;justify-content:space-between;border-top:0.6pt solid #3A1A28;padding-top:.5mm}
.ct .fld-v{height:6.4mm}
