(() => {
  root.querySelectorAll('.inner').forEach(el => {
    if (el.classList.contains('nopad')) return;
    const W0 = el.clientWidth, H0 = el.clientHeight;
    let z = 1;
    for (let k = 0; k < 4; k++) {
      const sh = el.scrollHeight, ch = el.clientHeight;
      if (sh <= ch + 1) break;
      z = z * ch / sh * 0.995;
      el.style.width = (W0 / z) + 'px';
      el.style.height = (H0 / z) + 'px';
      el.style.transform = 'scale(' + z + ')';
    }
  });
})()
