(() => {
  const MM = 96/25.4;
  root.querySelectorAll('.filltbl').forEach(el => {
    const rowH = 7.6*MM, tpl = el.dataset.row;
    const head = el.firstElementChild ? el.firstElementChild.getBoundingClientRect().height : 0;
    const n = Math.floor((el.clientHeight - head) / rowH);
    let h = '';
    for (let i = 1; i <= n; i++) h += tpl.split('{n}').join(String(i));
    el.insertAdjacentHTML('beforeend', h);
    el.style.gridTemplateRows = 'auto repeat(' + n + ', ' + (7.6) + 'mm)';
  });
  root.querySelectorAll('.ruled, .nt-lined').forEach(el => {
    const step = (el.classList.contains('nt-lined') ? 8 : 7.2);
    const n = Math.floor(el.clientHeight / (step*MM) + 0.02);
    el.style.backgroundImage = 'none'; el.style.overflow = 'hidden';
    el.style.display = 'flex'; el.style.flexDirection = 'column';
    let h = '';
    for (let i = 0; i < n; i++) h += '<div data-ln style="flex:0 0 ' + step + 'mm;border-bottom:0.5pt solid #CDB89A"></div>';
    el.innerHTML = h;
  });
  let k = 0;
  root.querySelectorAll('.nt-dot, .nt-grid').forEach(el => {
    const w = el.clientWidth, h = el.clientHeight, s = 5*MM; k++;
    const dot = el.classList.contains('nt-dot');
    const cols = Math.floor(w/s), rows = Math.floor(h/s);
    const ox = (w - cols*s)/2, oy = (h - rows*s)/2;
    let g = '';
    if (dot) {
      for (let r = 0; r <= rows; r++) for (let c = 0; c <= cols; c++)
        g += '<circle cx="'+(ox+c*s).toFixed(2)+'" cy="'+(oy+r*s).toFixed(2)+'" r="1.15" fill="#B9A27E"/>';
    } else {
      for (let c = 0; c <= cols; c++) g += '<line x1="'+(ox+c*s).toFixed(2)+'" y1="'+oy.toFixed(2)+'" x2="'+(ox+c*s).toFixed(2)+'" y2="'+(oy+rows*s).toFixed(2)+'" stroke="#E0D1BA" stroke-width="0.8"/>';
      for (let r = 0; r <= rows; r++) g += '<line x1="'+ox.toFixed(2)+'" y1="'+(oy+r*s).toFixed(2)+'" x2="'+(ox+cols*s).toFixed(2)+'" y2="'+(oy+r*s).toFixed(2)+'" stroke="#E0D1BA" stroke-width="0.8"/>';
    }
    el.style.backgroundImage = 'none'; el.style.border = 'none';
    el.innerHTML = '<svg width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'" style="display:block">'+g+'</svg>';
  });
})()
